gaVr(){return"Betonte und unbetonte Schl\xe4ge"},
gaUN(){return"p und f (piano/forte)"},
gaVt(){return"Italienische Tempo-W\xf6rter"},
gaVi(){return"Einen geh\xf6rten Rhythmus nachklatschen"},
gaVq(){return"Schritte und Spr\xfcnge"},
gaUC(){return"Die C-Dur-Tonleiter"},
